use calmcore::util::CoreResult;
use calmcore::{Action, ActionType, CalmCore, Config};
use proto::core::field::fulltext_option::Tokenizer;
use proto::core::field::Option::Fulltext;
use proto::core::field::Option::Term;
use proto::core::field::{FulltextOption, TermOption, Type};
use proto::core::Schema;

fn main() {
    env_logger::Builder::from_env(env_logger::Env::default().default_filter_or("debug")).init();

    let data_path = "data/calm_test";

    let _ = std::fs::remove_dir_all(data_path);

    // build_index("calmcore_bench", data_path).unwrap();

    // let sql = "select * from \"calmcore-bench\" where id='https://en.wikipedia.org/wiki?curid=48497249'";
    let sql = "select * from calmcore_bench where text='obstruction'";
    do_query("calmcore_bench", sql, data_path).unwrap();
}

fn do_query(schema_name: &str, sql: &str, data_path: &str) -> CoreResult<()> {
    //env_logger::Builder::from_env(env_logger::Env::default().default_filter_or("debug")).init();

    let core = CalmCore::new(data_path)?;
    let engine = core.load_engine(schema_name)?;

    let result = engine.sql(format!("{sql}").as_str())?;
    println!("sql result:{:?}", result.to_wrapper());

    Ok(())
}

fn build_index(schema_name: &str, data_path: &str) -> CoreResult<()> {
    let schema = make_schema(schema_name);
    let core = CalmCore::new(data_path)?;
    let space = core.create_engine(schema)?;

    let batch_size = 1;
    let mut actions = Vec::with_capacity(batch_size);

    let line = r#"{"id": "https://en.wikipedia.org/wiki?curid=48126401", "text": " vladimir tsyganko vladimir vladimirovich tsyganko also ganco tziganco tziganko or iganco was a bessarabian and later soviet politician the son of a distinguished architect and himself an engineer by vocation tsyganko entered politics shortly before the proclamation of a moldavian democratic republic when he earned a seat in the republican legislature sfatul rii he sided with the parliamentary peasants faction which supported left wing ideals and pushed for land reform being generally and radically opposed to the more right wing moldavian bloc tsyganko was skeptical of the bloc s plan to unite bessarabia with romania although he possibly supported a federation his uncompromising stance divided his faction and led the romanian kingdom s authorities to identify him as a major obstruction to the unionist cause in november as the bloc switched its support to unconditional unification and dissolved the regional government bodies tsyganko rejected the new regime and moved to odessa allying himself to members of the white movement with whom he set up a committee for the salvation of bessarabia attending the paris peace conference to campaign for the reversal of the union he later settled in soviet territory where he helped create a moldavian autonomous soviet socialist republic other members of his family opted to stay behind in romania in tsyganko fell victim to the great purge biography early career tsyganko was born in kishinev chi in u regional capital of the bessarabian governorate russian empire and was a graduate of riga polytechnicum he returned to his native city where his father vladimir an architect designed such landmarks as the ethnography museum and saint nicholas church his brother nikolai nicolai vladimirovich born was the zemstvo engineer in orhei and from in kishinev itself by their father was the director of monastery estates in bessarabia in which capacity he testified against russian police after the kishinev pogrom accusing them of passivity in the bessarabian journalist alexis nour described tsyganko sr as a much esteemed bessarabian intellectual of a moldavian nationalist hue but not a separatist see moldovenism also according to nour nikolai whom he met personally could speak only russian romanian politician duiliu zamfirescu who met and debated with vladimir vladimirovich in claimed that the tsygankos were ruthenian he and his adversary talked in french as tsyganko could not speak a word of romanian tsyganko reached political prominence after the october revolution which had left bessarabia to administer itself independently as a moldavian democratic republic in january the local soviet of workers and soldiers deputies began to override the sfatul rii assembly appointed the previous november and attempted to bring about bolshevik rule this move was swiftly suppressed by a punitive expedition of the romanian army the rd peasants congress assembled few days after the occupation of chi in u adopted an anti secessionist position dismissed the moldavian prime minister pantelimon erhan from the position of president of the peasants soviet and elected a new leadership from among the most vocal opponents of the romanian intervention according to the rumcherod s newspaper during the opening session tsyganko s message on behalf of the local socialist revolutionary branch was met with applause and calls to support the russian revolution the following day after demanding the withdrawal of romanian troops within hours and negotiating on the issue with the romanian military the congress presidium was put under arrest general ernest bro teanu dismissed the immunity of those peasants representatives who were also members of sfatul and issued a strong warning against further anti romanian agitation consequently the following days the congress selected a new list of sfatul representatives headed by tsyganko which comprised mostly moderates clashes with the unionists tsyganko who was counted among the representatives of the russian minority affiliated with the left wing peasants faction which stood in opposition to the moldavian bloc of romanian nationalists during the debates on land reform he suggested postponing the discussion until a new government representative of the people s will would be approved by a moldavian constituent assembly presumably he feared that pressure from the romanian troops would affect the extent of the reform nevertheless he became the first chairman of sfatul s agrarian commission and in parallel presided upon the peasants soviet despite being involved in left wing politics tsyganko would gradually develop a working relationship with andrei krupenski the polono bessarabian landowner and ex marshal of nobility and alexandr k schmidt who stood for the conservative side of anti romanian agitation between and the three men issued calls for the end of romanian occupation and began popularizing their cause in europe when romanian premier alexandru marghiloman traveled to bessarabia to canvass for the unionist cause he found the peasant faction divided between followers of ion incule who endorsed the romanian viewpoint and deputies who sided with tsyganko zamfirescu who traveled with marghiloman recalls that tsyganko thrice in one month attempted to recall the republic s directorate his moves resisted by incule he also protested the selection of pro romanian students from kiev and odessa as representatives of the transnistrian moldavians in which he saw efforts to shake the balance of power inside the sfatul zamfirescu claims to have saved tsyganko from an undisclosed mortal danger and then to have conversed with him trying to gain insight into his political motivations the latter he concluded were most phantasmagorical socialist ideas not dissuaded by the prospect of death suffering military disaster sheer destitution or degeneracy he adds it was late at night i was experiencing chills and so i believe i have insulted the convictions of this visionary youth reassuring him that all opinions lead to a ministerial chair provided one makes sure to discard them on cue despite proclaiming its independence in late february the moldavian republic was still seen in various circles as subordinate to the neighboring ukrainian people s republic its central rada wished to represent bessarabia in the preliminary negotiation of the bucharest peace treaty imposed by the central powers on romania the moldavian regional assembly reacted by reaffirming its independence and rejecting the division of bessarabia against the decisions of akkerman and khotin zemstva which had proclaimed their accession to the ukraine a moldavian delegation was therefore selected to head to kiev and obtain from the central rada official recognition of moldavia s independence the delegation which included the interior minister vladimir cristi the nationalists nicolae secar and teodor neaga and tsyganko as representative of the peasants faction was prevented from leaving according to the unionist gheorghe andronachi it was daniel ciugureanu the republic s pro romanian prime minister who intervened with the romanian army to hamper the departure fearing that an international recognition of independence would hinder nationalist plans for union with romania march union vote on march when sfatul voted to support the union with romania tsyganko effectively abstained zamfirescu found it unbelievable that romanian speaking peasants had ever endorsed tsyganko who he claimed systematically opposes bessarabia s government and romania s policies endeavoring for its annexation to the ukraine however he also notes that tsyganko himself accused the romanians of wanting to hand in bessarabia to the ukrainians a radical project for land reform had received pledges of support from sfatul secretary ion buzdugan and also from the marghiloman himself consequently according to historian alberto basciani tsyganko s critique of unionism became marginal within his own party and soviet on behalf of the peasant faction tsyganko denied the assembly had the authority to discuss such and issue declaring his group would refrain from voting since they considered this a matter for a constitutional convention furthermore he stated the only admissible terms for a union between the moldavian and romanian peoples would be in a federation five members of his faction decided to side with the nationalists and voted for the union while the other present abstained researchers are divided in their assessments of tsyganko s political stance at that early stage basciani describes him as one of those who opposed with great vehemence the union of bessarabia with romania however according to svetlana suveic tsyganko did not object to union with autonomy and in fact saw it as the only solution for avoiding the bolshevik invasion of the region in november after the generalization of romanian military rule in bessarabia tsyganko as putative president of the bessarabian peasants party with nicolae alexandri ion p sc lu and other sfatul members sent a letter of protest to the romanian government of constantin coand this coalition of romanian bessarabians and white russians demanded the immediate recognition and restoration of autonomy as well as the lifting of the martial law however its imperatives were rejected as illegitimate by the central authorities according to clark we cannot but applaud the admirable aims of the deputies in most of their requests but at the same time we must wonder at their ingenuousness they did not foresee the constant turbulence on the eastern frontier which even at that time impressed the roumanians november union vote the protest arose controversy in political circles tsyganko reported a private interview with the romanian envoy artur v itoianu he quoted the latter as offering a deal you must renounce autonomy if only for this sole reason hat you no good roumanian officials in bessarabia hat is to say none who are good nationalists if you give up autonomy you will not have a commissioner general but you will have a bessarabian charg d affaires a man of your own character who will be nominated by the central power the new bessarabian directorate will remain in office until the meeting of the pan roumanian constitutional assembly does this appeal to you as attractive also according to tsyganko v itoianu informed the group that they needed to coalesce with romanian nationalists in front of great russian revivalism and that the national idea takes precedence over everything implicitly threatening sfatul dignitaries as suveic writes it was only at this stage that tsyganko became an adversary of the unionist camp placing his hopes in a reestablishment of the russian republic and her re annexation of bessarabia at the last sfatul session on november unconditional union was proposed for ratification as one of several measures being voted on alongside the allocation of offices and a land reform law according to the peasants faction account also supported by many of the moldavian nationalists who had signed the earlier protest the moldavian bloc kept the opposition uniformed about there being a sfatul session only mr v tziganko was aware of the fact and he was informed privately two hours before the opening of the sitting the tsyganko group confronted the assembly s president halippa arguing that his election was illegal they announced another walk out to which voices of the moldavian bloc responded with rhetorical questions is this how you intend to solve the agrarian issue and taunts of good riddance the opposition maintained that the walk out resulted in a lack of quorum only of deputies were reportedly present which made the voting results questionable tsyganko and his colleagues accused the bloc of putting up unconditional union for the vote as a rider at am on the morning of november and counted the votes during considerable and purposeful commotion some of the fraction deputies in the opposition including tsyganko and gavril buciu can actually returned in time to cast their nay votes clark claims that one of the moldavian bloc representatives testified that there were enough deputies present according to moldavian bloc s pan halippa tsyganko s walk out from the assembly hall proved to be a miscalculation as the peasant faction s other members returned to vote on land reform and subsequently on the unconditional union marghiloman nevertheless gave a contrasting account he complained that not even deputies had been present for the vote abrogating the conditions in spite of all the money spent salvation committee in early tsyganko emigrated from what was then being recognized as romanian territory he settled in odessa a ukrainian port city where he established the peasants faction in exile alongside a dozen other former sfatul deputies he joined efforts with krupenski and schmidt affiliating with their committee for the salvation of bessarabia whose activities were closely monitored by romania s secret police the siguran a according to the moldavian bloc s petru cazacu they answered indirectly to anton denikin commander of the volunteer army the various groups of bessarabian autonomists and white loyalists agreed to send a common delegation to the peace conference in paris where the allies were debating on recognizing the union on february the committee issued a common platform for these organizations sharing two goals the liberation of bessarabia from the romanian annexation and the realization of the aspirations of the people of bessarabia the latter referred to the region s reintegration into russia in april together with krupenski and schmidt later followed by mark slonim and mihail savenco tsyganko had arrived in paris in its addresses to the international media the group insisted that the union was a putsch by urban intellectuals against the other social classes it also circulated a protest against the romanian land reform project which the salvation committee saw as a chauvinistic attack against the landed gentry and the russian patriots as noted by suveic tsyganko was the only delegation member to belong to a non aristocratic elite and nominally an appointee of the central committee of the peasants of bessarabia he therefore took some distance from the conservative demands of the salvation committee and in various contexts presented himself as an independent emissary united with the others mainly in their common support for a plebiscite clause in bessarabia however his autonomism and krupenski s loyalism were mostly endorsed by the white migr lobby in paris including the likes of georgy lvov vasily maklakov sergey sazonov and nikolai tchaikovsky in his papers halippa commented that tsyganko the self proclaimed socialist and revolutionary had arrived in paris as a propagandist of russian nationalism with no connection to the people of bessarabia cazacu also notes that the bizarre association comprising tsyganko maklakov and schmidt propagated the contradictory claim that sfatul was a bolshevik assembly in june the french communist organ l humanit gave exposure to slonim and tsyganko s allegations regarding political repression and atrocities in bessarabia as a common protest of the democrats and socialists such allegations were responded to by the bp s ion pelivan who wrote the newspaper to argue that romania s intervention had first of all restored liberty and democracy in bessarabia and that the union expressed the free will of the bessarabian populace with no outside intervention countering tsyganko s claim to speak for the peasants the pro romanian delegation grew to include peasant members such as ion codreanu gheorghe n stase and sergiu victor cujb later life making his split from the white russian community a definitive one tsyganko eventually settled in the ukrainian soviet socialist republic in september he wrote a memorandum on bessarabia and romania ussia relations which he sent to leon trotsky the commissar for military affairs his text informed the russian viewpoint at the negotiations in warsaw between the soviets and the romanians but also presented personal observations on the social makeup of bessarabia tsyganko argued that the moldavian republic s creation and union were attributable to left wing agitators such as incule and pantelimon erhan he claimed that multi ethnic bessarabia was naturally internationalist but also rural and well off concluding that an anti romanian revolt could happen if sustained from across the border cazacu noted in that the dossier compiled by the bolsheviks and the earlier salvation committee drafts used as sources the same documents including statements by private individuals in tsyganko became a founding figure of the moldavian autonomous soviet socialist republic created on soviet territory as a bessarabian rump state in september he was at odessa where together with ivan krivorukov he issued a formal protest against italy s recognition of the bessarabian union with romania and therefore against her passage into the anti soviet camp nikolai vladimirovich meanwhile remained behind in romania working as a conservator for the historical monuments commission then as department head for chi in u city hall in early nikolai supported the bessarabian regionalist platform for administrative reform an initiative by erhan and alexandru m he died some five years later at age while reading a book at some point during the s vladimir tsyganko was singled out as a political suspect by the stalinist regime and was murdered in at the height of the great purge "}"#;

    actions.push(Action::new(ActionType::Insert, "", line.as_bytes()));

    space.mutate(actions, None)?;

    space.persist()?;

    Ok(())
}

fn make_schema(schema_name: &str) -> Schema {
    calmcore::easy_schema(
        schema_name,
        vec![
            (
                "id".to_string(),
                Type::String,
                Some(Term(TermOption {
                    no_index: false,
                    no_store: false,
                })),
            ),
            (
                "text".to_string(),
                Type::Text,
                Some(Fulltext(FulltextOption {
                    tokenizer: Tokenizer::Standard as i32,
                    filters: Vec::new(),
                    stopwords: None,
                    synonyms: None,
                    no_store: true,
                })),
            ),
        ],
    )
}
